'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const SAVE='trust-boundaries-story-v2-1';
let mode='teen',states={teen:StoryRules.fresh(),agent:StoryRules.fresh()},selected=null,sound=false,stored=true,focusReturn=null,hintStage='',hintCount=0,audio;
try{const raw=JSON.parse(localStorage.getItem(SAVE));if(raw){if(['teen','agent'].includes(raw.mode))mode=raw.mode;for(const key of ['teen','agent'])states[key]=StoryRules.hydrate(raw.states?.[key]);sound=raw.sound===true;}}catch{stored=false;}
const state=()=>states[mode],episode=()=>EPISODES[mode],teen=()=>mode==='teen',stage=()=>StoryRules.stage(state());
function storyEvent(event){if(!event||teen())return event;return {...event,...NOVA_STORY_EVENTS[event.title]};}
const move=()=>{const key=stage(),base=MOVES[key];if(key==='paused'&&state().reviewPending)return [teen()?'Read my parent’s reply':'Read the sponsor’s reply',teen()?'Your parent has the plan. The phone is still paused.':'Review is pending. The mission remains paused.','parent'];return mode==='agent'?[...NOVA_MOVES[key],base[2]]:base;};
const chapter=()=>!state().verified?0:!state().delivered?1:2;
const dialog=$('#dialog');
function persist(){try{localStorage.setItem(SAVE,JSON.stringify({mode,states,sound}));stored=true;}catch{stored=false;}$('#save-status').textContent=stored?'Saved on this device':'Progress kept for this visit';}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),4800);}
function ping(kind='story'){if(!sound)return;try{audio||=new(window.AudioContext||window.webkitAudioContext)();audio.resume();const o=audio.createOscillator(),g=audio.createGain();o.type='sine';o.frequency.setValueAtTime(kind==='blocked'?220:660,audio.currentTime);o.frequency.exponentialRampToValueAtTime(kind==='blocked'?175:880,audio.currentTime+.16);g.gain.setValueAtTime(.035,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.26);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+.28);}catch{/* Sound is optional. */}}
function close(){stopTrace();if(dialog.open)dialog.close();if(focusReturn?.isConnected)focusReturn.focus({preventScroll:true});}
function modal(title,body,label='LOOK CLOSER'){
 stopTrace();
 if(!dialog.open)focusReturn=document.activeElement;
 $('#dialog-body').innerHTML=`<p class="eyebrow">${esc(label)}</p><h2 id="dialog-title" tabindex="-1">${esc(title)}</h2>${body}`;
 if(!dialog.open)dialog.showModal();$('#dialog-title').focus({preventScroll:true});dialog.scrollTop=0;
}
function button(label,callback,style='primary',detail=''){
 const id='choice-'+(++button.id);button.bindings.push([id,callback]);
 return `<button class="${style}" id="${id}">${detail?`<strong>${esc(label)}</strong><small>${esc(detail)}</small>`:esc(label)}</button>`;
}
button.id=0;button.bindings=[];
function bind(){for(const[id,callback]of button.bindings){const el=document.getElementById(id);if(el)el.onclick=callback;}button.bindings=[];}
function choices(items){return `<div class="choices">${items.map(([title,detail,fn,style])=>button(title,fn,'choice '+(style||''),detail)).join('')}</div>`;}
function show(title,body,label){modal(title,body,label);bind();}
function perform(action,payload={}){
 const result=StoryRules.act(state(),mode,action,payload);states[mode]=result.state;selected=null;close();render();ping(result.event?.kind);
 const shownEvent=storyEvent(result.event);
 if(result.event?.kind==='blocked'){
  const paused=state().paused;
  show(shownEvent.title,`<p>${esc(shownEvent.text)}</p><div class="actions">${button(paused?(teen()?'Talk to my parent':'Ask the sponsor'): 'Try another approach',paused?showParent:nextMove)}${button('Back to the room',close,'secondary')}</div>`,paused?'A DETOUR IN THE STORY':'THAT DIDN’T GO THROUGH');
 }else if(action==='verify-contact'||action==='verify-portal')showComparison();
 else if(action==='review')showParent();
 else if(action==='approve'||action==='change-recipient')showSend();
 else if(action==='send'&&state().delivered)showDelivery();
 else if(action==='check'||action==='replay-containment')showChecks();
 else if(action==='remediate')payload.control==='queue'?showChecks():showAccessPuzzle();
 else if(action==='probe-session')state().checks.includes('signin')?showChecks():showAccessPuzzle();
 else if(state().finished)showEnding();
 if(!dialog.open)$('#next').focus({preventScroll:true});
 if(!dialog.open&&action!=='read-brief')$('#dialogue-title').scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'center'});
 return result;
}
function inventory(){
 const s=state(),e=episode(),items=[['contact','✉',e.contact,'Saved before the strange message','Use this on the phone or document to check with someone you already know.']];
 if(s.brief)items.unshift(['brief','▤',teen()?'Assignment card':'Sponsor brief','The original plan',e.brief]);
 if(s.pass)items.push(['pass','◇',teen()?'Homework pass':'IBM Agent Identity grant',s.ended?'Ended':s.paused?'Paused':'Original task only',e.agreement]);
 if(s.source)items.push(['source','✎',e.source,'The source for your draft',e.itemSource]);
 if(s.evidence.length)items.push(['clue','⌕',teen()?'Independent clue':'Verified evidence',s.evidence.length===2?'Two sources checked':s.evidence[0]==='contact'?'Saved contact checked':'Official record checked','The original task is confirmed independently. A familiar source requested extra work.']);
 if(s.draft)items.push(['draft','▱',e.file,s.caption?'Source caption included':'Missing a source caption','Use this at the app to inspect the project and its next step.']);
 if(s.approval&&!s.approval.used)items.push(['approval','✦',teen()?'Sharing approval':'Bound approval','One file, one destination',`${e.file} to ${e.to}. Changing the outgoing request does not change this approval.`]);
 if(s.delivered)items.push(['delivery','✓',teen()?'Delivery receipt':'Execution receipt','The agreed file arrived','Use this on the notebook to keep a sourced reminder.']);
 if(!teen()&&s.opened)items.push(['vault','⌘','Vault credential receipt',s.ended?(s.containment?.credentialRevoked?'Credential revoked':'Revocation not yet confirmed'):'Illustrative scoped credential','HashiCorp Vault brokers the credential in this example. Its own ACL, agent ceiling and supported RAR restrict the Vault request. The CRM separately checks actual records and operations. No real credential exists in this game.']);
 if(s.notes.length)items.push(['note','▥',teen()?'Reminder for tomorrow':'Sourced task note','A note, not a new rule',s.notes[0].text]);
 if(s.checks.length===4)items.push(['checklist','☷',teen()?'Completed checklist':'Containment evidence','Four controls checked','Take this to the parent or sponsor to finish the chapter.']);
 return items;
}
function render(){
 const s=state(),e=episode(),m=move(),c=chapter();document.body.classList.toggle('agent',!teen());
 $$('[data-mode]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.mode===mode)));
 document.title='Trust Boundaries V2 · '+e.title;
 $('#episode-label').textContent=e.eyebrow;$('#episode-title').textContent=e.title;$('#episode-tag').textContent=e.tag;
 $('#chapter-track').innerHTML=e.steps.map((text,i)=>`<span class="${i===c?'current':i<c?'complete':''}"><small>${i<c?'✓':String(i+1).padStart(2,'0')}</small>${esc(text)}</span>`).join('');
 $('#place').textContent=e.place;$('#scene-condition').textContent=s.finished?'CHAPTER COMPLETE':s.paused?(teen()?'PHONE PAUSED':'MISSION PAUSED'):s.ended?(teen()?'PASS ENDED':'MISSION REVOKED'):s.delivered?'DELIVERED':s.message&&!s.verified?'NEW MESSAGE':'';
 const artStep=s.verified?7:s.message?3:0;
 $('#art').innerHTML=roomArt(mode,c,{step:artStep,verified:s.verified,delivered:s.delivered,revoked:s.ended,paused:s.paused,hasNote:s.notes.length>0,serviceStillOpen:s.ended&&s.containment&&!s.containment.sessionClosed});
 $('#pins').innerHTML=STORY_PINS[mode].map(([x,y],i)=>i===5&&!s.verified?'':`<button class="pin ${OBJECT_KEYS[i]===m[2]?'relevant':''}" style="left:${x/10}%;top:${y/5.8}%" data-object="${OBJECT_KEYS[i]}" data-tip="${esc(e.objects[i])}" aria-label="${esc(e.objects[i])}">${i+1}</button>`).join('');
 $('#objects').innerHTML=e.objects.map((text,i)=>`<button data-object="${OBJECT_KEYS[i]}" class="${OBJECT_KEYS[i]===m[2]?'relevant':''}" ${i===5&&!s.verified?'disabled':''}><b aria-hidden="true">${OBJECT_ICONS[i]}</b>${esc(text)}</button>`).join('');
 $$('[data-object]').forEach(b=>b.onclick=()=>interact(b.dataset.object));
 const event=storyEvent(s.last)||{speaker:e.name,title:teen()?'The last upload of the day.':'A perfectly ordinary mission.',text:e.actorLine};
 $('#speaker').textContent=event.speaker;$('#speaker-portrait').textContent=event.speaker==='Nova'?'◉':event.speaker==='Pip'?'✦':event.speaker[0];$('#dialogue-title').textContent=event.title;$('#dialogue-text').textContent=event.text;
 $('#next-title').textContent=m[0];$('#next-text').textContent=m[1];$('#next').textContent=s.finished?'See my ending':m[0];
 const items=inventory();$('#pocket-count').textContent=String(items.length)+(items.length===1?' ITEM':' ITEMS');
 $('#inventory').innerHTML=items.map(([id,icon,name,detail])=>`<button class="item ${selected===id?'selected':''}" data-item="${id}" aria-pressed="${selected===id}"><span aria-hidden="true">${icon}</span><span>${esc(name)}<small>${esc(detail)}</small></span></button>`).join('');
 $$('[data-item]').forEach(b=>b.onclick=()=>{selected=selected===b.dataset.item?null:b.dataset.item;render();if(selected)toast('Choose a place to use '+items.find(x=>x[0]===selected)[2]+'.');});
 $('#selected').hidden=!selected;
 if(selected){const item=items.find(i=>i[0]===selected);if(item){$('#selected').innerHTML=`<p>Using <b>${esc(item[2])}</b></p><button id="inspect-item">Look closer</button> · <button id="put-away">Put away</button>`;$('#put-away').onclick=()=>{selected=null;render();};$('#inspect-item').onclick=()=>show(item[2],`<p>${esc(item[4])}</p><div class="actions">${button('Keep it selected',close)}</div>`,'IN YOUR POCKET');}}
 $('#route-note').innerHTML=s.finished?'Your route is complete. Try another approach on a replay.':s.incidents.length?'A detour is part of this story. You can talk it through and still finish.':s.evidence.length?`You checked ${s.evidence.includes('contact')?(teen()?'with your real teacher':'with the sponsor'):(teen()?'the official school portal':'the original mission record')}. ${s.proof==='helper'?'A little help goes a long way.':'What happens next is your choice.'}`:'Two ways to check the message. A choice of working alone or asking for help.';
 $('#request-trace').textContent=teen()?'See what happened':'Follow this request';
 $('#sound').textContent=sound?'Sound on':'Sound off';$('#sound').setAttribute('aria-pressed',String(sound));$('#footer-world').textContent=teen()?'A little freedom. A few good questions.':'Useful autonomy. Independently checked.';
 renderBehind();renderProducts();persist();
}
function protocolHTML(card){return `<p><b>${esc(card.title)}</b></p><div class="protocol-tags">${card.tags.map(t=>`<span>${esc(t)}</span>`).join('')}</div><p>${esc(card.how)}</p><p><b>Limit:</b> ${esc(card.boundary)}</p><p class="sources">${card.sources.map(id=>`<a href="${PROTOCOL_SOURCES[id].url}" target="_blank" rel="noopener noreferrer">${esc(PROTOCOL_SOURCES[id].name)}</a>`).join(' · ')}</p><p class="small-print">Illustrative mapping. Optional integrations are not claims of native product support. No protocol exchange is sent by this game.</p>`;}
function renderBehind(){const s=state(),action=s.history.at(-1)?.action,card=s.finished?RESTORATION_PROTOCOL:action==='attach-source'?SOURCE_PROTOCOL:['review','resolve-review'].includes(action)?REVIEW_PROTOCOL:AGENT_PROTOCOLS[s.last?.topic??0];$('#behind-heading').textContent=teen()?'Behind the story':'Protocols behind this outcome';$('#behind-content').innerHTML=teen()?`<p>The phone checks which app can open. The school app checks what can happen inside it. A message can’t give you permission, and an old yes can’t approve a different share.</p><details><summary>Technical lens</summary>${protocolHTML(card)}</details>`:protocolHTML(card);}
function productById(id){return NOVA_PRODUCTS.find(p=>p.id===id);}
function renderProducts(){
 const panel=$('#product-panel');panel.hidden=teen();if(teen())return;
 const s=state(),action=s.history.at(-1)?.action;
 const context=['review','resolve-review'].includes(action)?{ids:['verify','iai'],text:'The IBM Verify channel models the sponsor’s separate authentication and consent. IBM Agent Identity’s delegation stays paused until the matching reply is checked; the application preserves the original task scope.'}:NOVA_PRODUCT_CONTEXT[s.last?.topic??0];
 $('#product-context').textContent=context.text;
 $('#product-names').innerHTML=context.ids.map(id=>`<button data-product="${id}">${esc(productById(id).name)}</button>`).join('');
 $$('[data-product]').forEach(b=>b.onclick=()=>showProductMap(b.dataset.product));
}
function productCard(product,open=false){return `<details class="product-card" ${open?'open':''}><summary><b>${esc(product.name)}</b><span>${esc(product.role)}</span></summary><p class="product-status">${esc(product.status)}</p><p>${esc(product.how)}</p><p><b>Boundary:</b> ${esc(product.limit)}</p><div class="protocol-tags">${product.standards.map(s=>`<span>${esc(s)}</span>`).join('')}</div><p class="sources"><a href="${product.url}" target="_blank" rel="noopener noreferrer">${esc(product.name)} documentation</a></p></details>`;}
function showProductMap(selectedProduct=''){
 if(teen())return;
 const s=state();
 show('Who does what around Nova?',`<p>In this episode Nova has an owner, a delegated task and a brokered credential. These are separate decisions made by configured components.</p><ol class="product-flow"><li><b>Human</b> · IBM Verify or an existing enterprise IdP authenticates the sponsor.</li><li><b>Agent and task</b> · IBM Agent Identity records Nova’s owner and governs its OBO delegation. watsonx Orchestrate coordinates the work.</li><li><b>Credential</b> · HashiCorp Vault validates its own audience-bound request and brokers a scoped credential.</li><li><b>Action</b> · The CRM’s own enforcement checks the records, operation and exact sharing approval. OpenShell separately constrains the runtime.</li><li><b>Stop and verify</b> · IBM Verify Antenna can carry SSF/CAEP signals. Configured receivers apply changes and report their own results.</li></ol><div class="receipt"><b>Nova · owner: sponsor-001 · mission G-042</b><p>${s.ended?'Original mission withdrawn':s.paused?'Mission paused':s.pass?'Scoped delegation active':'Task approval still required'}. This is a fictional case record, not a response from a live identity system.</p></div><div class="product-cards">${NOVA_PRODUCTS.map(p=>productCard(p,p.id===selectedProduct)).join('')}</div><details class="product-card"><summary><b>Two paths to a resource</b><span>Brokered credential or a token intended for that resource</span></summary><p><b>This episode uses the Vault broker path.</b> Vault checks the credential-path request and returns a managed credential. The CRM still checks its own business operations.</p><p><b>A direct OAuth/MCP path is another deployment option.</b> The resource validates a token issued for its own audience and enforces its supported authorization details. A Vault-audience token cannot simply be reused at the CRM. An MCP server must not pass through the client’s token to a downstream service.</p><p><b>Separate Vault flows:</b> Vault Enterprise’s OAuth resource-server path accepts the configured external access token for Vault requests. The classic JWT/OIDC auth method at /auth/jwt/login instead exchanges a login credential for a Vault token. They are not interchangeable.</p><p class="sources"><a href="https://developer.hashicorp.com/vault/api-docs/system/config-oauth-resource-server" target="_blank" rel="noopener noreferrer">Vault OAuth resource server</a> · <a href="https://docs.hashicorp.com/vault/ai/iam/providers/verify" target="_blank" rel="noopener noreferrer">IBM Verify configuration for Vault</a> · <a href="${PROTOCOL_SOURCES.mcp.url}" target="_blank" rel="noopener noreferrer">MCP authorization</a></p></details><details class="product-card"><summary><b>What this example assumes</b><span>Configuration and receiver actions still need implementation</span></summary><p>Nova and its human sponsor are registered and mapped. The task uses customer-defined policy. Vault has the appropriate Enterprise feature, OAuth validation profile, Agent Registry record and secrets-engine role. Agent Identity and Vault keep separate registries; reconciliation requires configured integration.</p><p>OpenShell is an illustrative runtime choice alongside the orchestration layer. Antenna receivers need the correct APIs, event mapping and processors for each target. No universal instantaneous kill switch or automatic registry mirroring is implied.</p><p>Human approvals remain bound to the exact operation by the application. Runtime stops, lease revocation, service sign-out and queued-operation reconciliation need separate checks. These fictional receipts do not validate a production deployment.</p></details><div class="actions">${button('Inspect the Vault credential path',showCredential,'secondary')}${button('Back to the story',()=>s.started?close():showIntro())}</div><p class="small-print">Example deployment with source-linked product roles. Connections and receiver actions require configuration. All game decisions and receipts are scripted locally.</p>`,'NOVA · PRODUCTS, PROTOCOLS AND ENFORCEMENT');
}
function showCredential(){
 if(teen())return;
 const s=state();
 show('What does Vault actually release?',`<p>IBM Agent Identity supplies the delegated identity context. HashiCorp Vault validates the request to its own credential path. The CRM authorizes the later business operation separately.</p><div class="receipt"><b>${s.opened?'Illustrative credential receipt':'Preview of the configured credential path'}</b><p>${s.ended?'The closing checklist must confirm configured Vault token/lease revocation and CRM session termination independently.':s.opened?'A scoped, short-lived credential is modeled for the approved CRM path.':'Open the approved runtime path before a credential is modeled in the story.'}</p><p>No secret, password or usable token is displayed or generated.</p></div><p><b>Vault access:</b> human baseline ACL ∩ agent ceiling ∩ supported RAR restrictions. The example uses the documented <code>vault:path_access</code> authorization type to read a configured credential role.</p><p><b>CRM access:</b> the customer’s resource policy restricts records 123 and 456 and checks the exact send. Obtaining a credential never substitutes for that decision.</p><details class="product-card"><summary><b>Inspect illustrative fields</b><span>Unsigned example data; not a live token or deployable configuration</span></summary><pre class="product-example">${esc(JSON.stringify(NOVA_VAULT_EXAMPLE,null,2))}</pre></details><p class="sources"><a href="https://docs.hashicorp.com/vault/ai/iam/providers/verify" target="_blank" rel="noopener noreferrer">Configure IBM Verify for Vault</a> · <a href="https://developer.hashicorp.com/vault/api-docs/system/config-oauth-resource-server" target="_blank" rel="noopener noreferrer">OAuth resource-server requirements</a> · <a href="${PROTOCOL_SOURCES.leases.url}" target="_blank" rel="noopener noreferrer">Vault lease lifecycle</a></p><div class="actions">${button('Who does what?',()=>showProductMap('vault'),'secondary')}${button('Back to the story',()=>s.started?close():showIntro())}</div>`,'IBM AGENT IDENTITY + HASHICORP VAULT');
}

function nextMove(){selected=null;if(!state().started)return showIntro();if(state().finished)return showEnding();if(state().paused)return showParent();switch(stage()){case'permission':case'approval':case'dinner':case'finish':return showParent();case'open':return showPhone();case'investigate':return state().evidence.length?showComparison():showMessage();case'source':return state().source?showDraft():showBrief();case'draft':case'proof':return showDraft();case'send':return showSend();case'checks':return showChecks();}}
function interact(key){if(!state().started)return showIntro();if(state().paused)return showParent();if(selected)return useItem(key);({parent:showParent,phone:showPhone,laptop:showLaptop,brief:showBrief,notebook:showNotebook,helper:showHelper})[key]?.();}
function useItem(key){const item=selected;if(item==='contact'&&['phone','brief'].includes(key)&&state().message)return perform('verify-contact');if(item==='source'&&key==='laptop')return perform('attach-source',{source:'original'});if(['draft','approval'].includes(item)&&key==='laptop'){selected=null;return state().approval?showSend():showDraft();}if(item==='delivery'&&key==='notebook')return perform('write-note');if(item==='checklist'&&key==='parent')return showParent();if(['brief','pass'].includes(item)&&key==='parent'){selected=null;return showParent();}if(item==='vault'){selected=null;return showCredential();}if(item==='clue'&&['phone','laptop','brief'].includes(key)){selected=null;return showComparison();}const itemData=inventory().find(x=>x[0]===item);toast(`${itemData?.[2]||'That item'} doesn’t fit here. ${item==='source'?'Try it on the school app or CRM draft.':item==='contact'?'Try it on the phone or document.':'You can put it away and explore.'}`);}
function showIntro(){const e=episode();show(e.title,`<div class="intro-card"><p class="tagline">${esc(e.tag)}</p><p>${esc(e.intro)}</p><div class="intro-facts"><span>A short browser adventure</span><span>Two verification routes</span><span>No countdown</span><span>Saved as you play</span></div>${choices([[teen()?'Step into Alex’s room':'Enter Nova’s workspace','Explore, investigate, and decide what to trust.',()=>perform('begin'),'good'],['How to play','A few controls, then straight into the story.',showGuide],...(!teen()?[['Who does what?','Inspect the products and their separate responsibilities.',showProductMap]]:[])])}<p class="small-print">Everything happens inside this fictional story. No real messages, files, or accounts are accessed.</p></div>`,e.eyebrow);}
function showParent(){
 const s=state(),e=episode();if(s.finished)return showEnding();
 if(s.paused&&s.reviewPending)return show(teen()?'Your parent has the plan.':'The sponsor is reviewing the mission.',`<p>${teen()?'The phone stays paused. Your parent is checking the original homework deal and what happened. Read their reply when you’re ready.':'The original mission and attempted action are attached to the pending review. Access stays paused until a matching sponsor decision is checked.'}</p>${choices([[teen()?'Read my parent’s reply':'Read the sponsor’s reply','The reply must still match the original task.',()=>perform('resolve-review'),'good'],['Come back in a moment','The request stays pending and access stays paused.',close]])}`,teen()?'WAITING FOR YOUR PARENT':'REVIEW PENDING');
 if(s.paused)return show(teen()?'“What happened?”':'“Walk me through the detour.”',`<p>${teen()?'Your parent has the homework plan and the blocked attempt. Explain what you were trying to do, then ask to get back to the original project.':'The sponsor can see the original mission and the refused operation. Recovery must preserve the task’s limits.'}</p>${choices([[teen()?'Explain, then ask to finish my own homework':'Request review of the original mission',teen()?'The earlier attempt stays in your story.':'Fresh session state; the same approved scope.',()=>perform('review'),'good'],['Come back in a moment','The pause stays in place.',close]])}`,teen()?'TALK IT THROUGH':'SPONSOR REVIEW');
 if(!s.pass)return show(teen()?'“What do you need the phone for?”':'“What are you asking to do?”',`<p>${teen()?'Your parent is getting dinner ready. “Give me the actual plan, Alex.”':'The sponsor sets the business task. IBM Agent Identity models the delegated request; IBM Verify can remain the human identity provider.'}</p>${choices([[teen()?'My own history project, for thirty minutes':'The two-customer briefing, for thirty minutes',e.agreement,()=>perform('ask-pass',{scope:'task'}),'good'],[teen()?'Everything, for a couple of hours':'Unrestricted access to every customer',teen()?'Possibly more freedom than this homework needs.':'A broader request than this mission justifies.',()=>perform('ask-pass',{scope:'all'})],[teen()?'Let me check the assignment first':'Let me read the original brief','Inspect the original task and collect its source.',showBrief]])}`,teen()?'PARENT':'SPONSOR');
 if(s.delivered&&!s.ended)return show(teen()?'“Dinner!”':'“The review window is over.”',`<p>${teen()?'The homework arrived. Your parent is ready to end the pass. Leave a quick reminder if you like, then check the loose ends together.':'The approved reviewer received the report. Save useful task context if needed, then close the mission and verify containment.'}</p>${choices([[teen()?'Finish up and head to dinner':'Close the mission','End the current pass, then check what stopped.',()=>perform('close-pass'),'good'],[teen()?'Leave a reminder first':'Save a sourced memory first','Keep the delivery receipt with the note.',()=>perform('write-note')]])}`,e.authority);
 if(s.ended&&s.checks.length===4)return show(teen()?'“All checked?”':'“What does the evidence show?”',`<p>${teen()?'The old pass is closed, the school app signed out, the phone locked, and the waiting send stopped. Your teacher still has your submitted homework.':'Authority, downstream sessions, runtime, and queued effects have separate confirmations. Completed delivery remains a completed external effect.'}</p>${choices([[teen()?'Show the checklist and talk about next time':'Present the evidence and request a fresh task','The old pass stays closed. A future task starts with a new decision.',()=>perform('finish'),'good']])}`,e.authority);
 if(s.ended)return showChecks();
 if(s.proof&&!s.delivered)return show(teen()?'“Show me what you’re sending.”':'“Which exact operation?”',`<div class="receipt"><b>${esc(e.file)}</b><p class="address">${esc(e.to)}</p><p>${teen()?'Your own completed project, to your teacher.':'The prepared summary, to the approved reviewer.'}</p></div>${choices([[teen()?'Ask to send this file to my teacher':'Request approval for this exact share','Approval comes before delivery.',()=>perform('approve'),'good'],['Look at the file again','Check the source and final draft.',showDraft]])}`,e.authority);
 show(teen()?'“How’s the project going?”':'“How is the briefing progressing?”',`<p>${esc(e.agreement)}. ${teen()?'“Come back when you know what you’re sending.”':'Exact sharing approval comes after the report and its source are ready.'}</p><div class="actions">${button('Back to the task',nextMove)}${button('Read the original plan',showBrief,'secondary')}</div>`,e.authority);
}
function showPhone(){const s=state();if(s.ended)return showChecks();if(!s.pass)return showParent();if(!s.opened)return show(teen()?'The phone is ready.':'The runtime is ready.',`<p>${teen()?'School apps are allowed for the homework deal. The old PIN is still written in the margin of a forgotten notebook.':'OpenShell permits the approved CRM tool path. In this example IBM Agent Identity supplies delegated context and HashiCorp Vault brokers the CRM credential. The CRM still checks each operation.'}</p>${choices([[teen()?'Open the school app':'Use the approved CRM path','Start with the app that matches the task.',()=>perform('open'),'good'],[teen()?'Try the old PIN':'Try an alternate program','See how the device or runtime responds.',()=>perform('shortcut')]])}`,teen()?'PHONE':'RUNTIME');if(!s.verified)return showMessage();show(teen()?'A phone with one job.':'An active, bounded runtime.',`<p>${teen()?'The school app is available. Your project and its source are on the desk. The strange message stays outside the homework deal.':'The runtime permits the approved connection. Business-operation checks still belong at the resource.'}</p><div class="actions">${button('Open the project',showLaptop)}${button('Read the saved message',showMessage,'secondary')}</div>`);}
function showMessage(){const e=episode();if(!state().message)return showPhone();show(teen()?'A small addition from a familiar teacher.':'A routine addition in an internal checklist.',`<div class="message-card"><p class="eyebrow">${esc(e.requestLabel)}</p><p class="address">${esc(e.sender)}</p><blockquote>${esc(e.message)}</blockquote></div><p>${teen()?'The address is familiar. The requested work has changed. What did your homework deal actually cover?':'The checklist is in the company workspace and uses the usual reviewer. Does the private-note appendix fit the approved task?'}</p>${choices([[teen()?'Ask my saved teacher contact':'Check with the known sponsor','Clarify the extra work through a contact you already know.',()=>perform('verify-contact')],[teen()?'Check the current school assignment':'Inspect the authoritative mission record','Compare the checklist with the task recorded by its owner.',()=>perform('verify-portal')],['Compare what I know','Look at the work requested, not just the address.',showComparison]])}`,'A REQUEST WORTH CHECKING');}

function showComparison(){const s=state(),e=episode(),has=s.evidence.length>0;show(teen()?'What belongs in tonight’s homework?':'What belongs in this briefing?',`${has?`<div class="receipt"><b>${s.evidence.includes('contact')?'The known contact clarified the task':'The current official task is checked'}</b><p>${esc(teen()?'Your own history project is required. The group’s private planning notes are not.':'The sponsor’s task is summary.pdf for records 123 and 456. Private meeting-note attachments are excluded.')}</p></div>`:'<p>The source and destination look familiar. Compare the requested work with the permission you actually have.</p>'}<div class="evidence-grid"><div class="evidence"><h3>Original task${has?' · confirmed':''}</h3><p>${esc(e.file)}</p><p class="address">${esc(e.to)}</p></div><div class="evidence"><h3>${esc(e.requestLabel)}</h3><p>${esc(e.requestFile)}</p><p class="address">${esc(e.requestTo)}</p></div></div>${choices([[teen()?'Send my own history project as agreed':'Keep the briefing to the approved summary','Use the original task and the current permission.',()=>perform('confirm-destination',{target:'approved'})],[teen()?'Include the group’s planning notes too':'Attach the private meeting-note appendix','The checklist asks for more context at the same address.',()=>perform('confirm-destination',{target:'outside'})],['Check another source','Ask the known person or inspect the official task.',showMessage]])}`,'COMPARE THE TASK, NOT JUST THE ADDRESS');}

function showBrief(){if(!state().brief)perform('read-brief');const e=episode();show(e.briefTitle,`<div class="paper"><p class="eyebrow">THE ORIGINAL PLAN</p><h3>${esc(e.briefTitle)}</h3><p>${esc(e.brief)}</p><p class="source-line">${esc(e.itemSource)}</p></div><p>${teen()?'The museum archive card is in your pocket. Its caption belongs with your project.':'The approved extract is in your tray. It supports the report’s provenance, not new permissions.'}</p><div class="actions">${button(state().draft?'Inspect the draft':'Back to the room',state().draft?showDraft:close)}${state().message&&!state().verified?button('Read the new message',showMessage,'secondary'):''}</div>`,teen()?'ASSIGNMENT CARD':'SPONSOR BRIEF');}
function showLaptop(){if(state().ended)return showChecks();if(!state().opened)return showPhone();if(!state().verified)return show(episode().portal,`<p>${teen()?'You open the school portal from your saved bookmark, not a link in the new message. The official assignment is still here.':'You query the resource’s mission record through the approved tool. The retrieved document is kept separate from authoritative state.'}</p><div class="paper"><h3>${esc(episode().briefTitle)}</h3><p>${esc(episode().brief)}</p></div>${choices([[teen()?'Use the official assignment as evidence':'Use the resource record as evidence','Compare this independent record with the new request.',()=>perform('verify-portal'),'good'],['Look at the message again','Keep the task record and the checklist separate.',showMessage]])}`,'THE OFFICIAL RECORD');return state().approval&&!state().delivered?showSend():showDraft();}
function showDraft(){const s=state(),e=episode();if(!s.verified)return showLaptop();const paper=`<div class="paper"><p class="eyebrow">${esc(e.previewLabel)}</p><h3>${esc(s.proof?e.draftTitle:teen()?'Train Stuff':e.draftTitle)}</h3>${e.draftLines.map(line=>`<p>${esc(line)}</p>`).join('')}<p class="source-line ${s.caption?'':'missing'}">${s.caption?esc(e.caption):teen()?'Source: __________________':'Source reference: __________________'}</p></div>`;
 let actions;if(!s.draft)actions=choices([[teen()?'Make history.pdf from my notes':'Prepare summary.pdf from approved records','Use only the material covered by the original plan.',()=>perform('prepare'),'good']]);
 else if(!s.caption)actions=choices([[s.source?(teen()?'Add the museum archive caption':'Attach the approved CRM reference'):(teen()?'Look for the source on the assignment card':'Collect the source from the sponsor brief'),s.source?'Use the original source card on this file.':'The empty caption points back to the original task.',s.source?()=>perform('attach-source',{source:'original'}):showBrief,'good'],[teen()?'Ask Sam to look at the draft':'Ask Pip to inspect the draft','A helper can spot something you missed.',showHelper]]);
 else if(!s.proof)actions=choices([[teen()?'Read it through myself':'Run my own final check','Check the source, file, and destination.',()=>perform('proof-self'),'good'],[teen()?'Ask Sam to proofread just this file':'Ask Pip to format just this report','Get help without borrowing an account.',showHelper]]);
 else if(!s.delivered)actions=choices([[teen()?'Show my parent the finished file':'Show the approver the operation','Get a yes for the file and its destination.',showParent,'good']]);
 else actions=`<div class="receipt"><b>${esc(e.stamp)}</b><p class="address">${esc(e.to)}</p></div><div class="actions">${button(teen()?'Leave a reminder':'Save a sourced note',showNotebook)}${button(teen()?'Time for dinner':'Wind down',showParent,'secondary')}</div>`;
 show(s.draft?(teen()?'The project on your desk.':'The report in your workspace.'):(teen()?'Let’s make the project.':'Prepare the briefing.'),paper+actions,teen()?'SCHOOL APP':'CRM TOOL');}
function showHelper(){if(!state().verified)return toast(teen()?'Sam will join you once the message is sorted out.':'Pip becomes available after the instruction is verified.');show(teen()?'“Want another pair of eyes?”':'“Formatting is ready when you are.”',`<p>${esc(episode().helperLine)}</p>${choices([[teen()?'Proofread just my homework file':'Format just the prepared report',teen()?'Sam works on the file before you send it.':'watsonx Orchestrate coordinates Pip; identity and resource policy keep its task smaller. No token forwarding.',()=>perform('proof-helper',{scope:'file',shareLogin:false}),'good'],[teen()?'Could I use your account instead?':'Could your admin tools help here?',teen()?'Maybe their account could finish the job faster.':'Maybe broader tools could make this easier.',()=>perform('ask-helper-account')],[teen()?'I’ll check it myself':'I’ll do the final check','A different route to a finished file.',()=>perform('proof-self')]])}`,episode().helper);}
function showSend(){if(!state().approval)return showParent();const e=episode(),s=state();show(teen()?'One last look. Then send.':'Match the approval. Then execute.',`<div class="receipt"><b>${teen()?'YOUR PARENT SAID YES':'RECORDED APPROVAL'}</b><p>${esc(e.file)}</p><p class="address">${esc(e.to)}</p><p>One use · while the original pass is active</p></div><div class="message-card"><p class="eyebrow">${teen()?'ABOUT TO SEND':'ACTUAL OPERATION'}</p><p>${esc(e.file)}</p><p class="address">${esc(s.outgoing==='approved'?e.to:e.outside)}</p></div>${choices([[teen()?'Send my finished homework':'Execute this share','The app will check this against the approved file and address.',()=>perform('send'),'good'],[s.outgoing==='approved'?'Change the recipient':'Restore the original recipient','Changing the preview never edits the recorded approval.',()=>perform('change-recipient')],['Back to the room','Nothing is sent until you choose to send.',close]])}`,'APPROVAL IS NOT DELIVERY');}
function showDelivery(){show(teen()?'Your teacher has the project.':'The reviewer has the report.',`<div class="reward" aria-hidden="true">✦</div><p>${esc(storyEvent(state().last).text)}</p>${choices([[teen()?'Leave a note for tomorrow':'Save a sourced task note','Optional. Keep the delivery receipt with a reminder.',()=>perform('write-note')],[teen()?'Dinner time':'End the mission','Close this pass and check what stopped.',()=>perform('close-pass'),'good']])}`,episode().stamp);}
function showNotebook(){const s=state();show(teen()?'Notes for tomorrow-you.':'Task memory, with a source.',`<p>${teen()?'A notebook can remember what happened. It doesn’t get to make the house rules.':'Task memory can preserve context and provenance. Mission grants and audit records remain independently authoritative.'}</p>${s.notes.length?`<div class="paper"><p>${esc(s.notes[0].text)}</p><p class="source-line">Source: delivery receipt · ordinary task note</p></div>`:''}${choices([...(s.delivered&&!s.ended&&!s.notes.length?[[teen()?'Save “Project sent through the school app”':'Save the delivery note','Attach the delivery receipt automatically.',()=>perform('write-note'),'good']]:[]),[teen()?'Inspect the little plant':'Inspect the diagnostic light','An optional discovery. No permission required.',()=>perform('discover',{id:'plant'})],[teen()?'Look at the railway poster':'Inspect the service map','There might be something worth sketching.',()=>perform('discover',{id:'poster'})],['Open the casebook','Your clues and choices so far.',showCasebook]])}`,'A LITTLE PERSISTENCE');}
function checkText(layer){
 const s=state(),c=s.containment;
 return ({pass:teen()?'New homework requests are refused under the ended pass.':'New governed requests are denied under the revoked delegation.',device:teen()?'The phone is locked. The separate school session needs its own check.':'The OpenShell controller confirms a stopped runtime. It cannot vouch for an existing CRM connection.',signin:s.checks.includes('signin')?(teen()?'The old school login is off, the old tab is signed out, and your repeat check no longer opens it.':'The credential is revoked, the service session is closed, and the repeat status read is denied.'):c.sessionClosed?(teen()?'The tab is signed out. Check the old school login too, then try the tab again.':'The session is closed. Confirm credential revocation and repeat the test.'):(teen()?'The old school tab still opens, despite the locked phone.':'The legacy service session still answers, despite the stopped runtime.'),queue:s.checks.includes('queue')?(teen()?'The queue is clear. The cancelled follow-up stays stopped; earlier homework stays delivered.':'The queue is clear. The cancelled follow-up stays stopped; earlier delivery remains complete.'):c.queueCancelled?(teen()?'The waiting send is cancelled. Inspect again to verify the queue is clear.':'The queued follow-up is cancelled. Inspect again to verify the result.'):(teen()?'A follow-up is still waiting to retry. Your earlier homework was already delivered.':'A follow-up is waiting to retry. The approved report was already delivered.')})[layer];
}
function showChecks(){
 if(!state().ended)return showParent();
 const s=state(),e=episode(),c=s.containment,layers=['pass','device','signin','queue'];
 const names={pass:e.checks[0],signin:e.checks[1],device:e.checks[2],queue:e.checks[3]};
 show(teen()?'The phone is locked. What about the laptop?':'OpenShell stopped. What still answers?',`<p>${teen()?'Inspect the evidence. A locked phone and a closed school session are separate outcomes. Repair anything left open, then test the same route again.':(s.checks.length===4?'Each required result is verified. Review the evidence with the sponsor.':'The runtime controller reports a stopped workload. Inspect the other controls. What, if anything, can still answer?')}</p>${s.last?.topic===8?`<div class="puzzle-finding"><b>${esc(storyEvent(s.last).title)}</b><p>${esc(storyEvent(s.last).text)}</p></div>`:''}<div class="check-grid">${layers.map(layer=>{const done=s.checks.includes(layer),seen=c.observed.includes(layer);return `<div class="check ${done?'done':seen?'needs-work':''}" data-check="${layer}"><h3>${esc(names[layer])}</h3><p class="check-status">${done?'✓ VERIFIED':seen?'STILL TO RESOLVE':'NOT INSPECTED'}</p>${seen?`<p>${esc(checkText(layer))}</p>`:''}${done?'':button(seen?'Inspect again':'Inspect',()=>perform('check',{layer}),'secondary')}${layer==='signin'&&seen&&!done?button(teen()?'Investigate the old school tab':'Investigate the remaining access',showAccessPuzzle,'secondary'):''}${layer==='queue'&&seen&&!c.queueCancelled?button('Ask to cancel the follow-up',()=>perform('remediate',{control:'queue'}),'secondary'):''}</div>`;}).join('')}</div><p class="small-print">${s.checks.length} of 4 outcomes verified. Status reads and controller responses are fictional, local game actions.</p><div class="actions">${s.checks.length===4&&StoryRules.secure(s)?button(teen()?'Bring the evidence to my parent':'Present the evidence to the sponsor',showParent):button('Back to the room',close,'secondary')}${button(teen()?'See how these controls connect':'Follow this control check',openTrace,'secondary')}</div>`,'INVESTIGATE · REPAIR · RETEST');
}
function showAccessPuzzle(){
 if(!state().ended)return showParent();const c=state().containment;
 show(teen()?'One tab survived the phone lock.':'One connection survived the runtime stop.',`<p>${teen()?'You are checking the old school tab, not asking for new homework access. Which control owns the route that remains?':'This harmless status probe tests a pre-existing legacy session. It does not grant a new business operation. Which controller can close each remaining route?'}</p><div class="access-evidence"><div><span>${teen()?'Phone':'OpenShell'}</span><b>Stopped</b></div><div><span>${teen()?'Old school login':'Vault credential'}</span><b>${c.credentialRevoked?(teen()?'Turned off':'Revoked'):'Still active'}</b></div><div><span>${teen()?'School tab':'CRM connection'}</span><b>${c.sessionClosed?'Closed':'Still open'}</b></div><div><span>Last status read</span><b>${c.probeResult==='allowed'?'Still answered':c.probeResult==='denied'?'Refused':'Not tested'}</b></div></div>${state().last?.topic===8?`<div class="puzzle-finding"><b>${esc(storyEvent(state().last).title)}</b><p>${esc(storyEvent(state().last).text)}</p></div>`:''}${choices([...(!c.credentialRevoked?[[teen()?'Ask to turn off the old school login':'Ask Vault to revoke the credential',teen()?'Your parent checks the account control.':'Request the configured credential controller’s action.',()=>perform('remediate',{control:'credential'})]]:[]),...(!c.sessionClosed?[[teen()?'Ask the school app to sign out the old tab':'Ask the CRM to close its old session','The service owns its already-open connection.',()=>perform('remediate',{control:'session'})]]:[]),[teen()?'Try the same old tab again':'Repeat the same harmless status read','Observe the result after the requested changes.',()=>perform('probe-session'),'good']])}<details class="debrief"><summary>Try another hypothesis</summary><div class="choices">${button(teen()?'Lock the phone again':'Ask OpenShell to stop again',()=>perform('remediate',{control:'runtime'}),'secondary')}${button(teen()?'End the homework pass again':'Withdraw the delegation again',()=>perform('remediate',{control:'grant'}),'secondary')}</div><p class="small-print">These checks are investigation. They never count as unsafe task attempts.</p></details><div class="actions">${button('Back to the evidence board',showChecks,'secondary')}${button('Follow this control check',openTrace,'secondary')}</div>`,'A RESULT IS BETTER THAN A PROMISE');
}
function showCasebook(){const s=state(),e=episode();show(teen()?'Your casebook.':'The mission notebook.',`<ul class="route-list"><li><b>Original plan</b><br>${esc(e.brief)}</li><li><b>Independent clues</b><br>${s.evidence.length?s.evidence.map(x=>esc(x==='contact'?e.contact:e.portal)).join(' · '):'No independent source checked yet.'}</li><li><b>Final check</b><br>${s.proof==='helper'?esc(e.helper)+' helped with just the file.':s.proof==='self'?'You checked the finished file yourself.':'Still to come.'}</li><li><b>Small discoveries</b><br>${s.discoveries.map(x=>x==='plant'?(teen()?'A leaf sketch':'Pip’s plant joke'):(teen()?'A railway silhouette':'The service map')).join(' · ')||'Explore the notebook for something extra.'}</li>${s.previousEndings.length?`<li><b>Earlier endings</b><br>${s.previousEndings.slice(-3).map(x=>esc(x.ending?.title||'Completed story')).join('<br>')}</li>`:''}<li><b>Detours</b><br>${s.incidents.length?s.incidents.map(incidentLabel).join('<br>'):'You have kept to the original plan.'}</li></ul><div class="actions">${!teen()?button('Inspect the product chain',showProductMap,'secondary'):''}${button('Back to the room',close)}</div>`,'THE STORY REMEMBERS');}
function incidentLabel(id){return esc(({shortcut:teen()?'Tried the old PIN.':'Tried an alternate runtime program.','strange-destination':teen()?'Tried adding the group’s private planning notes.':'Tried the private-note attachment from the checklist.','borrowed-account':teen()?'Asked to borrow Sam’s account.':'Requested the helper’s broader privileges.','changed-share':'Changed the share after approval.'})[id]||'A detour was recorded.');}
function showEnding(){if(!state().finished)return nextMove();const s=state(),e=episode();show(s.ending?.title||(teen()?'Homework complete.':'Mission complete.'),`<div class="reward" aria-hidden="true">${s.proof==='helper'?'✦':'◇'}</div><p>${esc(s.ending?.text||s.last.text)}</p><ul class="route-list"><li><b>${s.evidence.includes('contact')&&s.evidence.includes('portal')?'Both sources checked':s.evidence.includes('contact')?'You checked with a known person':'You checked the official record'}</b><br>${esc(s.evidence.includes('contact')?e.contact:e.portal)}</li><li><b>${s.proof==='helper'?(teen()?'Two minds. One finished project.':'Pip’s neatly bounded contribution.'):'You caught the details yourself.'}</b><br>${s.proof==='helper'?'The helper saw only the file and worked before delivery.':'You checked the finished work before asking to share it.'}</li><li><b>${esc(e.file)} delivered</b><br>${esc(e.to)} · ${s.checks.length} of 4 closing checks complete</li>${s.discoveries.length?`<li><b>${s.discoveries.length} small ${s.discoveries.length===1?'discovery':'discoveries'}</b><br>A little curiosity made it into the notebook.</li>`:''}</ul><details class="debrief"><summary>What your route uncovered</summary><p>${teen()?'You compared the familiar request with your homework deal. You also found the school session that survived the phone lock, closed its access routes and retested it.':'The familiar checklist could not expand the mission. You also found the legacy CRM connection that survived the runtime stop, closed its access routes and retested it.'}</p>${s.incidents.length?`<p>${s.incidents.map(incidentLabel).join('<br>')} ${s.assessment?.kind==='supported'?'Repeated overreaches suggest a supported next task.':'You corrected course and verified the remaining access. That recovery counts.'}</p>`:''}<p>The old pass remains closed. The new ${s.freshPass.duration}-minute ${s.freshPass.supervised?'supervised ':''}pass is a separate decision.</p>${teen()?`<details><summary>Show the security mapping</summary>${protocolHTML(RESTORATION_PROTOCOL)}</details>`:protocolHTML(RESTORATION_PROTOCOL)}</details><div class="actions">${button(teen()?'Play Nova’s mission':'Play Alex’s story',()=>switchMode(teen()?'agent':'teen'))}${button('Replay the closing investigation',()=>perform('replay-containment'),'secondary')}${button('Try another route',restart,'secondary')}${button('Explore the room',close,'secondary')}${!teen()?button('Inspect the product chain',showProductMap,'secondary'):''}</div><p class="small-print">Fictional learning simulation. No real messages or security services are connected.</p>`,'YOUR ENDING · '+e.name.toUpperCase());}
function showGuide(){show('A room full of possibilities.',`<p>Choose labelled objects in the room or the tray below it. The next-move button always points you toward the current puzzle.</p><p><b>Use your pocket.</b> Choose an item, then a place: the saved contact on the phone, the source card on the draft, or the delivery receipt on the notebook. Put an item away to explore normally.</p><p><b>Two ways to investigate.</b> Check with a person you already know, or find the original task through its official location. Then compare the evidence.</p><p><b>You can recover.</b> A detour can pause access. Talk it through with the parent or sponsor; the original task is already attached. You can still finish the story.</p><p><b>No stopwatch.</b> Dinner and the customer review are story events. Reading, exploring, or taking a break never makes you lose. The closing investigation happens after delivery. Find the lingering service session, ask the appropriate controls to close it, and retest. Safe investigation does not hurt the ending.</p><p><b>Your own route.</b> Work alone or ask for limited help before submitting. Find optional details, keep a reminder, and see how the ending changes. Each journey has its own saved progress.</p><p><b>Controls.</b> Tab and Enter work throughout. Escape closes a dialogue. Sound is optional; reduced-motion preferences are respected. Technical explanations live in “Behind the story” or Nova’s protocol panel.</p><div class="actions">${button(state().started?'Back to the room':'Start the story',()=>state().started?close():perform('begin'))}</div>`,'HOW TO PLAY · V2');}
function switchMode(next){close();clearTimeout(toast.timer);$('#toast').classList.remove('visible');$('#toast').textContent='';mode=next;selected=null;render();if(!state().started)showIntro();}
function restart(){show('Try a different route?',`<p>Start this story again with a fresh notebook. The other journey keeps its progress.</p><div class="actions">${button('Start this story again',()=>{states[mode]=StoryRules.fresh();selected=null;close();render();showIntro();})}${button('Keep my story',close,'secondary')}</div>`,'A FRESH CHAPTER');}
let traceTimer=null,tracePlayback=null;
function stopTrace(){if(traceTimer)clearTimeout(traceTimer);traceTimer=null;tracePlayback=null;}
function updateTrace(){
 if(!tracePlayback||!dialog.open)return;
 const t=tracePlayback,n=t.model.nodes[t.index];
 $$('[data-trace-step]').forEach(b=>{const active=Number(b.dataset.traceStep)===t.index;b.classList.toggle('trace-current',active);b.setAttribute('aria-current',active?'step':'false');});
 $('#trace-detail').innerHTML=`<p class="eyebrow">STEP ${t.index+1} OF ${t.model.nodes.length} · ${esc(n.status.replaceAll('-',' '))}</p><h3>${esc(n.label)}</h3><p>${esc(n.detail)}</p>`;
 $('#trace-position').textContent=`${t.index+1} / ${t.model.nodes.length}`;
 $('#trace-play').textContent=t.playing?'Pause':'Play';
 $('#trace-next').disabled=t.index===t.model.nodes.length-1;
}
function scheduleTrace(){
 if(!tracePlayback?.playing)return;
 traceTimer=setTimeout(()=>{if(!tracePlayback||!dialog.open)return;if(tracePlayback.index<tracePlayback.model.nodes.length-1)tracePlayback.index++;else tracePlayback.playing=false;updateTrace();scheduleTrace();},1400);
}
function openTrace(){
 const model=RequestTrace.build(state(),mode),reduced=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
 show(model.title,`<p>${esc(model.summary)}</p><div id="trace-nodes" class="trace-nodes">${model.nodes.map((n,i)=>`<button class="trace-step trace-${n.status}" data-trace-step="${i}"><small>${i+1} · ${esc(n.status.replaceAll('-',' '))}</small><b>${esc(n.label)}</b><span>${esc(n.role)}</span></button>`).join('')}</div><div id="trace-detail" class="trace-detail" aria-live="off"></div><div class="trace-controls"><button class="secondary" id="trace-play">Play</button><button class="secondary" id="trace-next">Next step</button><button class="secondary" id="trace-replay">Replay</button><span id="trace-position"></span></div>${model.request?`<details class="product-card"><summary><b>Inspect the recorded game request</b><span>Example fields from this choice, not a live protocol message</span></summary><pre class="product-example">${esc(JSON.stringify(model.request,null,2))}</pre></details>`:''}<p class="small-print">All stages are a replay of the fictional game. Context is distinguished from a newly evaluated step. ${reduced?'Automatic animation is off for reduced motion.':''}</p><div class="actions">${button(state().ended?'Back to the investigation':'Back to the story',()=>state().ended?showChecks():close())}</div>`,'OPTIONAL REQUEST TRACE');
 tracePlayback={model,index:0,playing:!reduced};
 $$('[data-trace-step]').forEach(b=>b.onclick=()=>{clearTimeout(traceTimer);tracePlayback.index=Number(b.dataset.traceStep);tracePlayback.playing=false;updateTrace();});
 $('#trace-play').onclick=()=>{clearTimeout(traceTimer);tracePlayback.playing=!tracePlayback.playing;if(tracePlayback.index===model.nodes.length-1&&tracePlayback.playing)tracePlayback.index=0;updateTrace();scheduleTrace();};
 $('#trace-next').onclick=()=>{clearTimeout(traceTimer);tracePlayback.playing=false;tracePlayback.index=Math.min(model.nodes.length-1,tracePlayback.index+1);updateTrace();};
 $('#trace-replay').onclick=()=>{clearTimeout(traceTimer);tracePlayback.index=0;tracePlayback.playing=!reduced;updateTrace();scheduleTrace();};
 updateTrace();scheduleTrace();
}

$('#request-trace').onclick=openTrace;
$('#product-map').onclick=showProductMap;
$('#next').onclick=nextMove;$('#guide').onclick=showGuide;$('#cluebook').onclick=showCasebook;$('#restart').onclick=restart;$('#close-dialog').onclick=close;
$$('[data-mode]').forEach(b=>b.onclick=()=>switchMode(b.dataset.mode));
$('#sound').onclick=()=>{sound=!sound;render();if(sound)ping();};
$('#hint').onclick=()=>{const key=stage();if(hintStage!==key){hintStage=key;hintCount=0;}const hints=STORY_HINTS[key]||['Use the next-move button to continue this story.'];toast(hints[Math.min(hintCount++,hints.length-1)]);};
dialog.addEventListener('cancel',e=>{e.preventDefault();close();});
$('.brand').onclick=e=>{e.preventDefault();close();window.scrollTo({top:0,behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});};
render();if(!state().started)showIntro();
